75	@RestController
76	@CrossOrigin(exposedHeaders = "errors, content-type")
77	@RequestMapping("/api")
78	public class OwnerRestControllerV1 implements OwnersApi {
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    private final OwnerFieldsValidator ownerFieldsValidator;
89	
90	    private final PostcodeValidator postcodeValidator;
91	
92	    private final RegistrationDateValidator registrationDateValidator;
93	
94	    private final HouseholdDuplicateValidator householdDuplicateValidator;
95	
96	    private final IdentityDuplicateValidator identityDuplicateValidator;
97	
98	    private final PossibleDuplicateDetector possibleDuplicateDetector;
99	
100	    private final HouseholdIdGenerator householdIdGenerator;
101	
102	    private final TelephoneNormalizer telephoneNormalizer;
103	
104	    private final EmailNormalizer emailNormalizer;
105	
106	    private final DisposableEmailDomainValidator disposableEmailDomainValidator;
107	
108	    private final AddressResolver addressResolver;
109	
110	    private final CustomerCodeGenerator customerCodeGenerator;
111	
112	    private final NamesakeCounter namesakeCounter;
113	
114	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
115	
116	    private final OwnerAuditLogger ownerAuditLogger;
117	
118	    public OwnerRestControllerV1(ClinicService clinicService,
119	                                 OwnerMapper ownerMapper,
120	                                 PetMapper petMapper,
121	                                 VisitMapper visitMapper,
122	                                 OwnerFieldsValidator ownerFieldsValidator,
123	                                 PostcodeValidator postcodeValidator,
124	                                 RegistrationDateValidator registrationDateValidator,
125	                                 HouseholdDuplicateValidator householdDuplicateValidator,
126	                                 IdentityDuplicateValidator identityDuplicateValidator,
127	                                 PossibleDuplicateDetector possibleDuplicateDetector,
128	                                 HouseholdIdGenerator householdIdGenerator,
129	                                 TelephoneNormalizer telephoneNormalizer,
130	                                 EmailNormalizer emailNormalizer,
131	                                 DisposableEmailDomainValidator disposableEmailDomainValidator,
132	                                 AddressResolver addressResolver,
133	                                 CustomerCodeGenerator customerCodeGenerator,
134	                                 NamesakeCounter namesakeCounter,
135	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
136	                                 OwnerAuditLogger ownerAuditLogger) {
137	        this.clinicService = clinicService;
138	        this.ownerMapper = ownerMapper;
139	        this.petMapper = petMapper;
140	        this.visitMapper = visitMapper;
141	        this.ownerFieldsValidator = ownerFieldsValidator;
142	        this.postcodeValidator = postcodeValidator;
143	        this.registrationDateValidator = registrationDateValidator;
144	        this.householdDuplicateValidator = householdDuplicateValidator;
145	        this.identityDuplicateValidator = identityDuplicateValidator;
146	        this.possibleDuplicateDetector = possibleDuplicateDetector;
147	        this.householdIdGenerator = householdIdGenerator;
148	        this.telephoneNormalizer = telephoneNormalizer;
149	        this.emailNormalizer = emailNormalizer;
150	        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
151	        this.addressResolver = addressResolver;
152	        this.customerCodeGenerator = customerCodeGenerator;
153	        this.namesakeCounter = namesakeCounter;
154	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
155	        this.ownerAuditLogger = ownerAuditLogger;
156	    }
157	
158	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
159	    @Override
160	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
161	        Collection<Owner> owners;
162	        if (lastName != null) {
163	            owners = this.clinicService.findOwnerByLastName(lastName);
164	        } else {
165	            owners = this.clinicService.findAllOwners();
166	        }
167	        if (owners.isEmpty()) {
168	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
169	        }
170	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
176	        Owner owner = this.clinicService.findOwnerById(ownerId);
177	        if (owner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
186	        addressResolver.resolve(ownerFieldsDto);
187	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
188	        if (!missingFields.isEmpty()) {
189	            throw new MissingOwnerFieldsException(missingFields);
190	        }
191	        HttpHeaders headers = new HttpHeaders();
192	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
193	        Collection<Owner> sameLastName =
194	            activeOwners(this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName()));
195	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
196	        List<Owner> householdMembers = assignHousehold(owner, sameLastName);
197	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
198	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
199	        disposableEmailDomainValidator.validate(owner.getEmail());
200	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
201	        rejectIfDuplicateIdentity(owner);
202	        applyHouseholdRule(owner, ownerFieldsDto, householdMembers, sameLastName);
203	        registrationDateValidator.validate(owner.getRegistrationDate());
204	        if (owner.getRegistrationDate() == null) {
205	            owner.setRegistrationDate(LocalDate.now());
206	        }
207	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
208	        LocalDate registrationDate = owner.getRegistrationDate();
209	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
210	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
211	            throw new DailyOwnerLimitException(registrationDate);
212	        }
213	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
214	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
215	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
216	            throw new CityOwnerLimitException(owner.getCity());
217	        }
218	        owner.setCustomerCode(assignCustomerCode(owner));
219	        this.clinicService.saveOwner(owner);
220	        ownerAuditLogger.ownerCreated(owner);
221	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
222	        headers.setLocation(UriComponentsBuilder.newInstance()
223	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
224	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
225	    }
226	
227	    /**
228	     * Assigns the household attributes of an owner about to be created, without touching any
229	     * existing owner. The {@code householdId} is derived deterministically from the owner's last
230	     * name and postcode, so every owner in the same household shares it automatically regardless of
231	     * creation order. The new owner's household size after this create is recorded: the existing
232	     * members that share its household (same last name and postcode) plus the owner itself.
233	     *
234	     * @return the existing members of the owner's household (empty when it starts a new household)
235	     */
236	    private List<Owner> assignHousehold(Owner owner, Collection<Owner> sameLastName) {
237	        owner.setHouseholdId(householdIdGenerator.generate(owner));
238	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
239	        owner.setHouseholdSize(members.size() + 1);
240	        return members;
241	    }
242	
243	    /**
244	     * Computes the customer code for an owner about to be created, de-duplicated against the codes
245	     * already assigned to existing owners so that distinct owners always receive distinct codes.
246	     *
247	     * @return the owner's unique customer code
248	     */
249	    private String assignCustomerCode(Owner owner) {
250	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
251	        String baseCode = customerCodeGenerator.generate(
252	            region, owner.getTelephone(), owner.getLastName());
253	        List<String> takenCodes = clinicService.findOwnersByCustomerCodeStartingWith(baseCode)
254	            .stream()
255	            .map(Owner::getCustomerCode)
256	            .toList();
257	        return customerCodeGenerator.deduplicate(baseCode, takenCodes);
258	    }
259	
260	    /**
261	     * Applies the household-membership rule once the owner has cleared hard duplicate detection.
262	     * When the owner joins an existing household (same last name and postcode) it is rejected as a
263	     * household duplicate, unless the request declared {@code sharesHousehold}: a declared member is
264	     * created and, being knowingly registered, is not treated as a suspected duplicate. When the
265	     * owner starts a new household the ordinary possible-duplicate detection runs.
266	     *
267	     * @throws HouseholdDuplicateException if the owner joins an existing household without opting in
268	     */
269	    private void applyHouseholdRule(Owner owner, OwnerFieldsDto ownerFieldsDto,
270	                                    List<Owner> householdMembers, Collection<Owner> sameLastName) {
271	        if (householdMembers.isEmpty()) {
272	            flagPossibleDuplicate(owner, sameLastName);
273	            return;
274	        }
275	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
276	            throw new HouseholdDuplicateException(owner.getHouseholdId());
277	        }
278	        owner.setPossibleDuplicate(false);
279	        owner.setPossibleDuplicateOf(null);
280	    }
281	
282	    /**
283	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
284	     * owner. A full-key match requires an equal telephone, so only owners with the same
285	     * (already normalized) telephone are compared.
286	     *
287	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
288	     */
289	    private void rejectIfDuplicateIdentity(Owner owner) {
290	        Collection<Owner> sameTelephone =
291	            activeOwners(this.clinicService.findOwnersByTelephone(owner.getTelephone()));
292	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
293	            throw new DuplicateIdentityException(IdentityKey.of(owner));
294	        }
295	    }
296	
297	    /**
298	     * Filters out soft-deleted owners, so the create endpoint's duplicate and identity checks
299	     * consider only owners that are still active. A soft-deleted owner keeps its row but is
300	     * treated as absent for the purpose of detecting duplicates of a newly created owner.
301	     */
302	    private List<Owner> activeOwners(Collection<Owner> owners) {
303	        return owners.stream().filter(candidate -> !candidate.isDeleted()).toList();
304	    }
305	
306	    /**
307	     * Flags the owner as a soft (possible) duplicate when it is not a hard duplicate yet shares an
308	     * existing owner's last name and postcode with a different telephone. The matching owner's id
309	     * is recorded in {@code possibleDuplicateOf}; when nothing matches the owner is stamped as not
310	     * a possible duplicate. Called after {@link #rejectIfDuplicateIdentity(Owner)}, so any candidate
311	     * seen here is guaranteed not to be a hard duplicate.
312	     */
313	    private void flagPossibleDuplicate(Owner owner, Collection<Owner> sameLastName) {
314	        Owner match = possibleDuplicateDetector.findPossibleDuplicate(owner, sameLastName).orElse(null);
315	        owner.setPossibleDuplicate(match != null);
316	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
317	    }
318	
319	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
320	    @Override
321	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
322	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
323	        if (currentOwner == null) {
324	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
325	        }
326	        currentOwner.setAddress(ownerFieldsDto.getAddress());
327	        currentOwner.setCity(ownerFieldsDto.getCity());
328	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
329	        currentOwner.setLastName(ownerFieldsDto.getLastName());
330	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
331	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
332	        this.clinicService.saveOwner(currentOwner);
333	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
334	    }
335	
336	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
337	    @Transactional
338	    @Override
339	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
340	        Owner owner = this.clinicService.findOwnerById(ownerId);
341	        if (owner == null) {
342	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
343	        }
344	        owner.setDeleted(true);
345	        this.clinicService.saveOwner(owner);
346	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
347	    }
348	
349	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
350	    @Override
351	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
352	        Owner owner = this.clinicService.findOwnerById(ownerId);
353	        if (owner == null) {
354	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
355	        }
356	        HttpHeaders headers = new HttpHeaders();
357	        Pet pet = petMapper.toPet(petFieldsDto);
358	        owner.setId(ownerId);
359	        pet.setOwner(owner);
360	        pet.getType().setName(null);
361	        this.clinicService.savePet(pet);
362	        PetDto petDto = petMapper.toPetDto(pet);
363	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
364	            .buildAndExpand(pet.getId()).toUri());
365	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
366	    }
367	
368	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
369	    @Override
370	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
371	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
372	        if (currentOwner != null) {
373	            Pet currentPet = this.clinicService.findPetById(petId);
374	            if (currentPet != null) {
375	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
376	                currentPet.setName(petFieldsDto.getName());
377	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
378	                this.clinicService.savePet(currentPet);
379	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
380	            }
381	        }
382	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
383	    }
384	
385	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
386	    @Override
387	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
388	        HttpHeaders headers = new HttpHeaders();
389	        Visit visit = visitMapper.toVisit(visitFieldsDto);
390	        Pet pet = new Pet();
391	        pet.setId(petId);
392	        visit.setPet(pet);
393	        this.clinicService.saveVisit(visit);
394	        VisitDto visitDto = visitMapper.toVisitDto(visit);
395	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
396	            .buildAndExpand(visit.getId()).toUri());
397	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
398	    }
399	
400	
401	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
402	    @Override
403	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
404	        Owner owner = this.clinicService.findOwnerById(ownerId);
405	        if (owner != null) {
406	            Pet pet = owner.getPet(petId);
407	            if (pet != null) {
408	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
409	            }
410	        }
411	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
412	    }
413	}
